import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), k = (int) nextLong();
        long[] p = new long[n + 1];
        for (int i = 1; i <= n; i++) p[i] = p[i - 1] + nextLong();
        // For right end r, subtract the smallest prefix p[0..r-k].
        long minimum = 0, answer = Long.MIN_VALUE;
        for (int r = k; r <= n; r++) {
            minimum = Math.min(minimum, p[r - k]);
            answer = Math.max(answer, p[r] - minimum);
        }
        System.out.println(answer);
    }
}

