	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)
	p := make([]int64, n+1)
	for i := 1; i <= n; i++ {
		var v int64
		fmt.Fscan(in, &v)
		p[i] = p[i-1] + v
	}
	// For right end r, subtract the smallest prefix p[0..r-k].
	var minimum int64
	var answer int64 = math.MinInt64
	for r := k; r <= n; r++ {
		minimum = min(minimum, p[r-k])
		answer = max(answer, p[r]-minimum)
	}
	fmt.Println(answer)
}
